def cart_reducer(state, action):
    import copy
    new_state = copy.deepcopy(state)
    items = new_state.get('items', [])
    discount = new_state.get('discount', 0.0)

    act_type = action.get('type')
    if act_type == 'ADD_ITEM':
        item = action['item']
        found = False
        for it in items:
            if it['id'] == item['id']:
                it['qty'] += 1
                found = True
                break
        if not found:
            new_item = dict(item)
            new_item['qty'] = 1
            items.append(new_item)
    elif act_type == 'REMOVE_ITEM':
        target_id = action['id']
        for it in list(items):
            if it['id'] == target_id:
                it['qty'] -= 1
                if it['qty'] <= 0:
                    items.remove(it)
                break
    elif act_type == 'APPLY_DISCOUNT':
        discount = action.get('percent', 0.0)

    raw_total = sum(i['price'] * i['qty'] for i in items)
    final_total = round(raw_total * (1.0 - discount / 100.0), 2)

    return {
        'items': items,
        'discount': discount,
        'total': final_total
    }

